import com.sun.fortress.tests.unit_tests.FileTests;
import edu.rice.cs.plt.iter.IterUtil;
import java.io.File;
import java.util.*;

public class SuiteI {
    public static void main(String[] a) throws Exception {
        boolean shuffle = a[0].equals("shuffle");
        long seed = Long.parseLong(a[1]);
        List<String> files = new ArrayList<String>(Arrays.asList(a).subList(2, a.length));
        Iterable<String> order = shuffle ? IterUtil.shuffle(files, new Random(seed)) : files;
        System.out.println("SuiteI order (" + (shuffle ? "shuffled, seed " + seed : "as given") + "):");
        for (String s : order) System.out.println("  " + s);
        String dir = new File(files.get(0)).getParent();
        junit.framework.TestSuite suite = FileTests.suiteFromListOfFiles(order, dir, dir, new File(dir).getCanonicalPath(), false, false);
        junit.framework.TestResult r = junit.textui.TestRunner.run(suite);
        System.out.println("SuiteI result: runs=" + r.runCount() + " failures=" + r.failureCount() + " errors=" + r.errorCount());
        System.exit(0);
    }
}
